from nose.tools import assert_equal
from luigi.contrib.hive import HiveTableTask, table_exists

class TableExistsTest(HiveTableTask):
    def __init__(self, table, database, *args, **kwargs):
        self.table = table
        self.database = database
        self.partition = None
        super(TableExistsTest, self).__init__(*args, **kwargs)

class TestTableExists(object):

    @classmethod
    def setup_class(cls):
        cls.table = 'foo'
        cls.database = 'bar'

    @classmethod
    def teardown_class(cls):
        pass

    def test_table_exists_true(self):
        assert_equal(True, table_exists(TableExistsTest(self.table, self.database), self.table, self.database))

    def test_table_exists_false(self):
        assert_equal(False, table_exists(TableExistsTest(self.table, self.database), 'notable', self.database))

    def test_table_exists_with_partition(self):
        assert_equal(False, table_exists(TableExistsTest(self.table, self.database, None, None), self.table, self.database, {'a':1}))

    def test_table_exists_with_partition_true(self):
        assert_equal(True, table_exists(TableExistsTest(self.table, self.database, None, None), self.table, self.database, {'a':2}))
